import { useState, useEffect } from "react";

// Router tối giản dựa trên location.hash (#/trang)
function useHashRoute() {
  const read = () => window.location.hash.slice(1) || "/";
  const [path, setPath] = useState(read);
  useEffect(() => {
    const on = () => setPath(read());
    window.addEventListener("hashchange", on);
    return () => window.removeEventListener("hashchange", on);
  }, []);
  return path;
}

function Link({ to, children }) {
  return <a href={"#" + to}>{children}</a>;
}

export default function App() {
  const path = useHashRoute();
  let page = <p id="page">Trang chủ</p>;
  if (path === "/about") page = <p id="page">Giới thiệu</p>;
  else if (path.startsWith("/user/")) page = <p id="page">Người dùng {path.split("/")[2]}</p>;
  return (
    <div>
      <nav><Link to="/">Home</Link> <Link to="/about">About</Link> <Link to="/user/7">User 7</Link></nav>
      {page}
    </div>
  );
}

